72	  bypass = kasan_bypass(true);
73	
74	  tmp = delay->head;
75	
76	#  if CONFIG_MM_FREE_DELAYCOUNT_MAX > 0
77	  if (tmp == NULL || (!force &&
78	      delay->delaycount < CONFIG_MM_FREE_DELAYCOUNT_MAX))
79	    {
80	      up_irq_restore(flags);
81	      return false;
82	    }
83	
84	  delay->delaycount = 0;
85	#  endif
86	
87	  delay->head = NULL;
88	
89	  kasan_bypass(bypass);
90	  up_irq_restore(flags);
91	
92	  /* Test if the delayed is empty */
93	
94	  ret = !!tmp;
95	
96	  while (tmp)
97	    {
98	      FAR void *address;
99	
100	      /* Get the first delayed deallocation */
101	
102	      address = tmp;
103	      tmp = tmp->flink;
104	
105	      /* The address should always be non-NULL since that was checked in the
106	       * 'while' condition above.
107	       */
108	
109	      mm_forcefree(heap, address);
110	    }
111	
112	#endif
113	  return ret;
114	}
